      P3(1, { k: "submit", payload: { x: Math.min(990, z2.x + Math.round(z2.r * 1.5)), y: z2.y } });
      P3(2, { k: "submit", payload: { x: Math.max(10, 1e3 - z2.x), y: Math.max(10, 600 - z2.y) } });
